<?php
require_once __DIR__.'/../../config/config.php';require_roles(['ADMIN','HR']);$pdo=db();$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$id=(int)($_POST['id']??0);$data=[trim($_POST['name']),trim($_POST['code']),post_value('description')];if(!$data[0]||!$data[1])throw new InvalidArgumentException('Name and code are required.');if($id){$pdo->prepare('UPDATE document_types SET name=?,code=?,description=? WHERE id=?')->execute([...$data,$id]);audit('TEMPLATE_TYPE_UPDATED','document_types',$id);}else{$pdo->prepare('INSERT INTO document_types (name,code,description) VALUES (?,?,?)')->execute($data);audit('DOCUMENT_TYPE_CREATED','document_types',(int)$pdo->lastInsertId());}flash('success','Document type saved.');redirect('admin/document-types/index.php');}catch(Throwable $exception){$error='Document type code must be unique.';}}$types=$pdo->query('SELECT * FROM document_types ORDER BY name')->fetchAll();$pageTitle='Document types';require __DIR__.'/../../includes/header.php';?><div class="flex justify-between mb-7"><h1 class="font-display text-3xl font-bold">Document types</h1></div><?php if($error):?><div class="mb-5 bg-red-50 p-3 text-sm text-red-700"><?=e($error)?></div><?php endif;?><div class="grid xl:grid-cols-[1fr_360px] gap-6"><section class="bg-white border rounded-xl p-6 space-y-3"><?php foreach($types as $type):?><div class="flex justify-between border-b pb-3"><span><b><?=e($type['name'])?></b><small class="block text-slate-400"><?=e($type['code'])?></small></span><span class="text-xs font-bold text-teal-700"><?= $type['is_active']?'Active':'Inactive'?></span></div><?php endforeach;?></section><form method="post" class="bg-white border rounded-xl p-6 space-y-3"><?= csrf_field() ?><h2 class="font-display text-xl font-bold">Add document type</h2><input name="name" required placeholder="Name" class="field"><input name="code" required placeholder="Unique code" class="field"><textarea name="description" placeholder="Description" class="field"></textarea><button class="rounded-lg bg-teal-700 px-4 py-3 text-sm font-bold text-white">Save type</button></form></div><?php require __DIR__.'/../../includes/footer.php';